1	package consensus
2	
3	import (
4		"crypto/ed25519"
5		"crypto/rand"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"testing"
11	)
12	
13	type testKey struct {
14		priv ed25519.PrivateKey
15		pub  ed25519.PublicKey
16	}
17	
18	func genKeys(t *testing.T, n int) []testKey {
19		t.Helper()
20		keys := make([]testKey, n)
21		for i := range keys {
22			pub, priv, err := ed25519.GenerateKey(rand.Reader)
23			if err != nil {
24				t.Fatal(err)
25			}
26			keys[i] = testKey{priv: priv, pub: pub}
27		}
28		return keys
29	}
30	
31	func newTestNode(t *testing.T, keys []testKey, maxTxs uint64) (*Node, string) {
32		t.Helper()
33		dir := t.TempDir()
34		vals := make([][]byte, len(keys))
35		for i, k := range keys {
36			vals[i] = k.pub
37		}
38		n, err := New(dir, Config{Seed: []byte("test-seed-v1"), Validators: vals, MaxTxsPerBlock: maxTxs})
39		if err != nil {
40			t.Fatal(err)
41		}
42		return n, dir
43	}
44	
45	func reason(err error) string {
46		var re *RejectError
47		if errors.As(err, &re) {
48			return re.Reason
49		}
50		return ""
51	}
52	
53	// 初始状态：轮次 1，账户确认序号 0，配置必须校验。
54	func TestInitialState(t *testing.T) {
55		keys := genKeys(t, 4)
56		n, _ := newTestNode(t, keys, 10)
57		if n.CurrentRound() != 1 {
58			t.Fatalf("initial round = %d, want 1", n.CurrentRound())
59		}
60		if n.Height() != 0 {
61			t.Fatalf("initial height = %d, want 0", n.Height())
62		}
63		acct := n.Account(keys[0].pub)
64		if acct.ConfirmedSequence != 0 {
65			t.Fatalf("initial confirmed seq = %d, want 0", acct.ConfirmedSequence)
66		}
67		if acct.Gap != 0 || len(acct.Pending) != 0 {
68			t.Fatalf("unexpected pending: %+v", acct)
69		}
70	
71		dir := t.TempDir()
72		cfg := Config{Seed: []byte("s"), Validators: [][]byte{keys[0].pub}, MaxTxsPerBlock: 1}
73		if _, err := New(dir, Config{Validators: cfg.Validators, MaxTxsPerBlock: 1}); err == nil {
74			t.Fatal("empty seed should be rejected")
75		}
76		if _, err := New(t.TempDir(), Config{Seed: []byte("s"), MaxTxsPerBlock: 1}); err == nil {
77			t.Fatal("empty validators should be rejected")
78		}
79		if _, err := New(t.TempDir(), Config{Seed: []byte("s"), Validators: cfg.Validators, MaxTxsPerBlock: 0}); err == nil {
80			t.Fatal("zero max txs should be rejected")
81		}
82		if _, err := New(t.TempDir(), Config{Seed: []byte("s"), Validators: [][]byte{keys[0].pub, keys[0].pub}, MaxTxsPerBlock: 1}); err == nil {
83			t.Fatal("duplicate validators should be rejected")
84		}
85	}
86	
87	// 签名编码与交易标识稳定。
88	func TestStableEncoding(t *testing.T) {
89		keys := genKeys(t, 1)
90		tx := NewTransaction(keys[0].priv, 7, []byte("hello"), 3, 99)
91		id1, sb1 := tx.ID(), tx.SigningBytes()
92		// 重新逐字节构造一份相同内容的交易，标识与签名编码必须一致。
93		tx2 := NewTransaction(keys[0].priv, 7, []byte("hello"), 3, 99)
94		if tx2.ID() != id1 {
95			t.Fatal("same bytes must yield same id")
96		}
97		if string(tx2.SigningBytes()) != string(sb1) {
98			t.Fatal("signing bytes must be stable")
99		}
100		if !tx2.Verify() {
101			t.Fatal("valid signature should verify")
102		}
103		// 篡改内容后签名失效。
104		tx2.Content = []byte("tampered")
105		if tx2.Verify() {
106			t.Fatal("tampered content must fail verification")
107		}
108		// 签名必须覆盖费用、到期轮次与序号。
109		txFee := NewTransaction(keys[0].priv, 7, []byte("hello"), 3, 99)
110		txFee.Fee++
111		if txFee.Verify() {
112			t.Fatal("tampered fee must fail verification")
113		}
114		txExp := NewTransaction(keys[0].priv, 7, []byte("hello"), 3, 99)
115		txExp.Expiry++
116		if txExp.Verify() {
117			t.Fatal("tampered expiry must fail verification")
118		}
119		txSeq := NewTransaction(keys[0].priv, 7, []byte("hello"), 3, 99)
120		txSeq.Sequence++
121		if txSeq.Verify() {
122			t.Fatal("tampered sequence must fail verification")
123		}
124		// 不同费用产生不同标识。
125		tx3 := NewTransaction(keys[0].priv, 7, []byte("hello"), 4, 99)
126		if tx3.ID() == id1 {
127			t.Fatal("different fee must yield different id")
128		}
129	}
130	
131	// 各种拒绝原因。
132	func TestSubmitRejections(t *testing.T) {
133		keys := genKeys(t, 4)
134		n, _ := newTestNode(t, keys, 10)
135	
136		// 非法签名
137		bad := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 10)
138		bad.Signature[0] ^= 0xff
139		if _, err := n.Submit(bad); reason(err) != ReasonBadSignature {
140			t.Fatalf("got %v, want %s", err, ReasonBadSignature)
141		}
142	
143		// 序号非正
144		zero := NewTransaction(keys[0].priv, 0, []byte("a"), 1, 10)
145		if _, err := n.Submit(zero); reason(err) != "sequence-must-be-positive" {
146			t.Fatalf("got %v, want sequence-must-be-positive", err)
147		}
148	
149		// 已到期：到期轮次不大于当前轮次 1
150		exp := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 1)
151		if _, err := n.Submit(exp); reason(err) != ReasonExpired {
152			t.Fatalf("got %v, want %s", err, ReasonExpired)
153		}
154	
155		ok := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 10)
156		res, err := n.Submit(ok)
157		if err != nil {
158			t.Fatal(err)
159		}
160	
161		// 完全相同的交易重复提交
162		if _, err := n.Submit(NewTransaction(keys[0].priv, 1, []byte("a"), 1, 10)); reason(err) != ReasonDuplicate {
163			t.Fatalf("got %v, want %s", err, ReasonDuplicate)
164		}
165	
166		// 同序号费用不更高
167		low := NewTransaction(keys[0].priv, 1, []byte("b"), 1, 10)
168		if _, err := n.Submit(low); reason(err) != ReasonLowFee {
169			t.Fatalf("got %v, want %s", err, ReasonLowFee)
170		}
171	
172		// 费用严格更高才能替换
173		hi := NewTransaction(keys[0].priv, 1, []byte("b"), 5, 10)
174		rep, err := n.Submit(hi)
175		if err != nil {
176			t.Fatal(err)
177		}
178		if rep.ReplacedID != res.TxID || rep.TxID != hi.ID() {
179			t.Fatalf("replacement result wrong: %+v", rep)
180		}
181		oldInfo, err := n.Tx(res.TxID)
182		if err != nil {
183			t.Fatal(err)
184		}
185		if oldInfo.Status != StatusReplaced || oldInfo.ReplacedBy != hi.ID() {
186			t.Fatalf("old tx status = %s replacedBy=%s, want replaced/%s", oldInfo.Status, oldInfo.ReplacedBy, hi.ID())
187		}
188		newInfo, _ := n.Tx(hi.ID())
189		if newInfo.Status != StatusQueued {
190			t.Fatalf("new tx status = %s, want queued", newInfo.Status)
191		}
192	}
193	
194	// 确认后序号不大于已确认序号被拒；缺口交易可入池等待，查询指出最早缺口。
195	func TestGapAndConfirmedSequence(t *testing.T) {
196		keys := genKeys(t, 4)
197		n, _ := newTestNode(t, keys, 10)
198	
199		tx2 := NewTransaction(keys[0].priv, 2, []byte("two"), 1, 100)
200		if _, err := n.Submit(tx2); err != nil {
201			t.Fatal(err)
202		}
203		acct := n.Account(keys[0].pub)
204		if acct.Gap != 1 || len(acct.Pending) != 1 {
205			t.Fatalf("gap = %d pending = %d, want gap 1", acct.Gap, len(acct.Pending))
206		}
207		if acct.Pending[0].Note != "waiting-pack" {
208			t.Fatalf("note = %q, want waiting-pack", acct.Pending[0].Note)
209		}
210	
211		tx1 := NewTransaction(keys[0].priv, 1, []byte("one"), 1, 100)
212		if _, err := n.Submit(tx1); err != nil {
213			t.Fatal(err)
214		}
215		acct = n.Account(keys[0].pub)
216		if acct.Gap != 0 {
217			t.Fatalf("gap = %d, want 0", acct.Gap)
218		}
219	
220		p, err := n.Propose()
221		if err != nil {
222			t.Fatal(err)
223		}
224		if len(p.TxIDs) != 2 || p.TxIDs[0] != tx1.ID() || p.TxIDs[1] != tx2.ID() {
225			t.Fatalf("block order wrong: %v", p.TxIDs)
226		}
227		confirmByVotes(t, n, keys, p.BlockID)
228		if n.CurrentRound() != 2 {
229			t.Fatalf("round = %d, want 2", n.CurrentRound())
230		}
231	
232		acct = n.Account(keys[0].pub)
233		if acct.ConfirmedSequence != 2 {
234			t.Fatalf("confirmed = %d, want 2", acct.ConfirmedSequence)
235		}
236		// 序号不大于已确认序号
237		replay := NewTransaction(keys[0].priv, 2, []byte("two"), 1, 100)
238		if _, err := n.Submit(replay); reason(err) != ReasonDuplicate {
239			t.Fatalf("same tx replay got %v, want duplicate", err)
240		}
241		oldSeq := NewTransaction(keys[0].priv, 1, []byte("one"), 9, 100)
242		if _, err := n.Submit(oldSeq); reason(err) != ReasonOldSequence {
243			t.Fatalf("got %v, want %s", err, ReasonOldSequence)
244		}
245	}
246	
247	// 打包顺序：跨账户按费用，同账户后续序号必须等前一条被选入；达到上限停止。
248	func TestPackingOrder(t *testing.T) {
249		keys := genKeys(t, 4)
250		n, _ := newTestNode(t, keys, 2)
251	
252		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 10, 100)
253		a2 := NewTransaction(keys[0].priv, 2, []byte("a2"), 100, 100) // 费用最高，但必须等 a1 选入后才可考虑
254		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 50, 100)
255		for _, tx := range []*Transaction{a1, a2, b1} {
256			if _, err := n.Submit(tx); err != nil {
257				t.Fatal(err)
258			}
259		}
260		p, err := n.Propose()
261		if err != nil {
262			t.Fatal(err)
263		}
264		// 第一次取各账户下一条：b1(50) 高于 a1(10)；第二次只有 a1 可确认，
265		// a2 因序号缺口本轮取不到，且已达上限 2。
266		want := []string{b1.ID(), a1.ID()}
267		if fmt.Sprint(p.TxIDs) != fmt.Sprint(want) {
268			t.Fatalf("packed %v, want %v", p.TxIDs, want)
269		}
270		// 确认后下一轮 a2 成为该账户下一条可确认交易并被打包
271		confirmByVotes(t, n, keys, p.BlockID)
272		p2, err := n.Propose()
273		if err != nil {
274			t.Fatal(err)
275		}
276		if len(p2.TxIDs) != 1 || p2.TxIDs[0] != a2.ID() {
277			t.Fatalf("round 2 packed %v, want [a2]", p2.TxIDs)
278		}
279	}
280	
281	// 费用相同时按交易标识字典序选择（确定性可复算）。
282	func TestTieBreakByID(t *testing.T) {
283		keys := genKeys(t, 4)
284		n, _ := newTestNode(t, keys, 1)
285		txs := make([]*Transaction, 4)
286		for i := range txs {
287			txs[i] = NewTransaction(keys[i].priv, 1, []byte("x"), 7, 100)
288			if _, err := n.Submit(txs[i]); err != nil {
289				t.Fatal(err)
290			}
291		}
292		p, err := n.Propose()
293		if err != nil {
294			t.Fatal(err)
295		}
296		minID := txs[0].ID()
297		for _, tx := range txs[1:] {
298			if tx.ID() < minID {
299				minID = tx.ID()
300			}
301		}
302		if len(p.TxIDs) != 1 || p.TxIDs[0] != minID {
303			t.Fatalf("picked %v, want lexicographically smallest %s", p.TxIDs, minID)
304		}
305	}
306	
307	// 重复请求返回同一提议；提议冻结后新交易不改变提议，提议中交易禁止替换。
308	func TestProposalStableAndFrozen(t *testing.T) {
309		keys := genKeys(t, 4)
310		n, _ := newTestNode(t, keys, 10)
311		tx1 := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100)
312		if _, err := n.Submit(tx1); err != nil {
313			t.Fatal(err)
314		}
315		p1, err := n.Propose()
316		if err != nil {
317			t.Fatal(err)
318		}
319		p2, err := n.Propose()
320		if err != nil {
321			t.Fatal(err)
322		}
323		if p1.BlockID != p2.BlockID || len(p2.TxIDs) != 1 || p2.TxIDs[0] != tx1.ID() {
324			t.Fatal("repeated proposal must be identical")
325		}
326		// 提议后再提交的交易不改变当前提议
327		tx2 := NewTransaction(keys[1].priv, 1, []byte("b"), 99, 100)
328		if _, err := n.Submit(tx2); err != nil {
329			t.Fatal(err)
330		}
331		p3, _ := n.Propose()
332		if len(p3.TxIDs) != 1 {
333			t.Fatalf("proposal changed after new submit: %v", p3.TxIDs)
334		}
335		// 提议中的交易禁止替换
336		replace := NewTransaction(keys[0].priv, 1, []byte("a2"), 999, 100)
337		if _, err := n.Submit(replace); reason(err) != ReasonProposalLocked {
338			t.Fatalf("got %v, want %s", err, ReasonProposalLocked)
339		}
340		info, _ := n.Tx(tx1.ID())
341		if info.Status != StatusProposed {
342			t.Fatalf("tx in proposal status = %s, want proposed", info.Status)
343		}
344		acct := n.Account(keys[0].pub)
345		if len(acct.Pending) != 1 || acct.Pending[0].Status != StatusProposed || acct.Pending[0].Note != "waiting-vote" {
346			t.Fatalf("proposed tx should show waiting-vote: %+v", acct.Pending)
347		}
348		// 未确认时结束轮次，交易回到排队状态
349		r, err := n.EndRound()
350		if err != nil {
351			t.Fatal(err)
352		}
353		if r != 2 {
354			t.Fatalf("round after end = %d, want 2", r)
355		}
356		acct = n.Account(keys[0].pub)
357		if acct.Pending[0].Status != StatusQueued || acct.Pending[0].Note != "waiting-pack" {
358			t.Fatalf("returned tx should be queued/waiting-pack: %+v", acct.Pending[0])
359		}
360		if _, ok := n.Proposal(); ok {
361			t.Fatal("proposal should be cleared after EndRound")
362		}
363		if n.Height() != 0 {
364			t.Fatal("ended round must leave no confirmed block")
365		}
366	}
367	
368	// 空块：没有可选交易时返回空块并按相同条件确认。
369	func TestEmptyBlock(t *testing.T) {
370		keys := genKeys(t, 4)
371		n, _ := newTestNode(t, keys, 10)
372		p, err := n.Propose()
373		if err != nil {
374			t.Fatal(err)
375		}
376		if !p.Empty || len(p.TxIDs) != 0 {
377			t.Fatalf("want empty proposal, got %+v", p)
378		}
379		emptyID := p.BlockID
380		confirmByVotes(t, n, keys, p.BlockID)
381		b, err := n.BlockAt(1)
382		if err != nil {
383			t.Fatal(err)
384		}
385		if b.ID != emptyID || len(b.TxIDs) != 0 || b.Height != 1 || b.Round != 1 {
386			t.Fatalf("empty block wrong: %+v", b)
387		}
388		if b.PreviousID != "" {
389			t.Fatalf("genesis previous id = %q, want empty", b.PreviousID)
390		}
391	}
392	
393	func confirmByVotes(t *testing.T, n *Node, keys []testKey, blockID string) {
394		t.Helper()
395		round := n.CurrentRound()
396		// N=4 需 >2/3，即至少 3 票。
397		count := len(keys)*2/3 + 1
398		for i := 0; i < count; i++ {
399			res, err := n.Vote(keys[i].pub, round, blockID)
400			if err != nil {
401				t.Fatalf("vote %d: %v", i, err)
402			}
403			if i < count-1 && res.Confirmed {
404				t.Fatalf("confirmed too early at vote %d", i+1)
405			}
406			if i == count-1 {
407				if !res.Confirmed || res.Block == nil {
408					t.Fatalf("vote %d should confirm", i+1)
409				}
410			}
411		}
412	}
413	
414	// 投票阈值、重复投票、非法投票拒绝。
415	func TestVoting(t *testing.T) {
416		keys := genKeys(t, 4)
417		n, _ := newTestNode(t, keys, 10)
418		p, _ := n.Propose()
419		round := n.CurrentRound()
420	
421		// 名单外身份
422		outsider := genKeys(t, 1)[0]
423		if _, err := n.Vote(outsider.pub, round, p.BlockID); reason(err) != ReasonNotValidator {
424			t.Fatalf("got %v, want %s", err, ReasonNotValidator)
425		}
426		// 错误轮次
427		if _, err := n.Vote(keys[0].pub, round+1, p.BlockID); reason(err) != ReasonWrongRound {
428			t.Fatalf("got %v, want %s", err, ReasonWrongRound)
429		}
430		// 错误区块标识
431		if _, err := n.Vote(keys[0].pub, round, "deadbeef"); reason(err) != ReasonWrongBlock {
432			t.Fatalf("got %v, want %s", err, ReasonWrongBlock)
433		}
434	
435		// 一票
436		res, err := n.Vote(keys[0].pub, round, p.BlockID)
437		if err != nil || !res.Counted || res.Confirmed {
438			t.Fatalf("first vote: %+v %v", res, err)
439		}
440		// 重复投同一票不增加票数
441		res, err = n.Vote(keys[0].pub, round, p.BlockID)
442		if err != nil || res.Counted {
443			t.Fatalf("duplicate vote: %+v %v", res, err)
444		}
445		// 第二票仍不确认（4 人需 3 票）
446		res, _ = n.Vote(keys[1].pub, round, p.BlockID)
447		if res.Confirmed {
448			t.Fatal("2/4 votes must not confirm")
449		}
450		// 第三票确认
451		res, _ = n.Vote(keys[2].pub, round, p.BlockID)
452		if !res.Confirmed {
453			t.Fatal("3/4 votes must confirm")
454		}
455		// 确认后旧轮次投票拒绝（轮次已前进）
456		if _, err := n.Vote(keys[3].pub, round, p.BlockID); reason(err) != ReasonWrongRound {
457			t.Fatalf("stale vote after confirm got %v, want wrong-round", err)
458		}
459	}
460	
461	// 链连续性：高度、前块标识、交易顺序，且交易查询关联区块。
462	func TestChainContinuity(t *testing.T) {
463		keys := genKeys(t, 4)
464		n, _ := newTestNode(t, keys, 10)
465	
466		tx1 := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100)
467		tx2 := NewTransaction(keys[1].priv, 1, []byte("b"), 2, 100)
468		n.Submit(tx1)
469		n.Submit(tx2)
470		p1, _ := n.Propose()
471		confirmByVotes(t, n, keys, p1.BlockID)
472	
473		tx3 := NewTransaction(keys[0].priv, 2, []byte("c"), 1, 100)
474		n.Submit(tx3)
475		p2, _ := n.Propose()
476		confirmByVotes(t, n, keys, p2.BlockID)
477	
478		b1, _ := n.BlockAt(1)
479		b2, _ := n.BlockAt(2)
480		if b1.Height != 1 || b2.Height != 2 {
481			t.Fatal("heights not continuous")
482		}
483		if b2.PreviousID != b1.ID {
484			t.Fatalf("previous id %s != %s", b2.PreviousID, b1.ID)
485		}
486		if b1.TxIDs[0] != tx2.ID() || b1.TxIDs[1] != tx1.ID() {
487			t.Fatalf("round 1 order wrong: %v", b1.TxIDs)
488		}
489		if b2.TxIDs[0] != tx3.ID() {
490			t.Fatalf("round 2 order wrong: %v", b2.TxIDs)
491		}
492		latest, ok := n.LatestBlock()
493		if !ok || latest.ID != b2.ID {
494			t.Fatal("latest block wrong")
495		}
496		info, _ := n.Tx(tx1.ID())
497		if info.Status != StatusConfirmed || info.BlockHeight != 1 || info.BlockID != b1.ID {
498			t.Fatalf("tx lookup wrong: %+v", info)
499		}
500		if _, err := n.BlockAt(3); reason(err) != ReasonUnknownBlock {
501			t.Fatalf("got %v, want unknown-block", err)
502		}
503		if _, err := n.Tx("nope"); reason(err) != ReasonUnknownTx {
504			t.Fatalf("got %v, want unknown-tx", err)
505		}
506	}
507	
508	// 进入新轮次时到期交易失效；旧轮次投票不能影响新提议。
509	func TestExpiryAndStaleVotes(t *testing.T) {
510		keys := genKeys(t, 4)
511		n, _ := newTestNode(t, keys, 10)
512	
513		tx1 := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 3) // 在进入轮次 3 时失效
514		n.Submit(tx1)
515		p1, _ := n.Propose()
516		// 不投票确认，直接结束轮次进入轮次 2，交易回池
517		n.EndRound()
518		p2, _ := n.Propose()
519		if len(p2.TxIDs) != 1 || p2.TxIDs[0] != tx1.ID() {
520			t.Fatalf("tx still valid in round 2: %v", p2.TxIDs)
521		}
522		// 旧轮次投票不能影响新提议
523		if _, err := n.Vote(keys[0].pub, 1, p2.BlockID); reason(err) != ReasonWrongRound {
524			t.Fatalf("got %v, want wrong-round", err)
525		}
526		if _, err := n.Vote(keys[0].pub, 2, p1.BlockID); reason(err) != ReasonWrongBlock {
527			t.Fatalf("got %v, want wrong-block", err)
528		}
529		// 结束轮次 2 进入轮次 3，tx1 到期
530		n.EndRound()
531		info, _ := n.Tx(tx1.ID())
532		if info.Status != StatusExpired {
533			t.Fatalf("status = %s, want expired", info.Status)
534		}
535		p3, _ := n.Propose()
536		if !p3.Empty {
537			t.Fatalf("expired tx must not be packed: %v", p3.TxIDs)
538		}
539		acct := n.Account(keys[0].pub)
540		if len(acct.Pending) != 0 {
541			t.Fatalf("expired tx must not remain pending: %+v", acct.Pending)
542		}
543	}
544	
545	// 停止再启动恢复全部状态。
546	func TestPersistenceRoundTrip(t *testing.T) {
547		keys := genKeys(t, 4)
548		dir := t.TempDir()
549		vals := make([][]byte, len(keys))
550		for i, k := range keys {
551			vals[i] = k.pub
552		}
553		n, err := New(dir, Config{Seed: []byte("persist-seed"), Validators: vals, MaxTxsPerBlock: 5})
554		if err != nil {
555			t.Fatal(err)
556		}
557		txQ := NewTransaction(keys[0].priv, 2, []byte("gap"), 1, 100) // 缺口，留在池中
558		n.Submit(txQ)
559		tx1 := NewTransaction(keys[1].priv, 1, []byte("a"), 4, 100)
560		n.Submit(tx1)
561		p, _ := n.Propose()
562		n.Vote(keys[0].pub, 1, p.BlockID) // 仅一票，提议与票数未决
563	
564		n2, err := Open(dir)
565		if err != nil {
566			t.Fatal(err)
567		}
568		if n2.CurrentRound() != 1 {
569			t.Fatalf("round restored = %d", n2.CurrentRound())
570		}
571		p2, ok := n2.Proposal()
572		if !ok || p2.BlockID != p.BlockID || len(p2.TxIDs) != len(p.TxIDs) {
573			t.Fatalf("proposal not restored: %+v", p2)
574		}
575		// 重复投票不计数：keys[0] 的票已随状态恢复
576		res, err := n2.Vote(keys[0].pub, 1, p.BlockID)
577		if err != nil || res.Counted {
578			t.Fatalf("restored vote dedup failed: %+v %v", res, err)
579		}
580		// 再补两票即可确认，池内缺口交易仍在
581		res, _ = n2.Vote(keys[1].pub, 1, p.BlockID)
582		res, _ = n2.Vote(keys[2].pub, 1, p.BlockID)
583		if !res.Confirmed {
584			t.Fatal("restored node should reach confirmation")
585		}
586		acct := n2.Account(keys[0].pub)
587		if acct.Gap != 1 || len(acct.Pending) != 1 || acct.Pending[0].ID != txQ.ID() {
588			t.Fatalf("pool not restored: %+v", acct)
589		}
590		// 确认历史与账户序号
591		b, _ := n2.BlockAt(1)
592		if b.ID != p.BlockID {
593			t.Fatal("history not restored")
594		}
595		if a := n2.Account(keys[1].pub); a.ConfirmedSequence != 1 {
596			t.Fatalf("confirmed seq restored = %d", a.ConfirmedSequence)
597		}
598	
599		// New 拒绝覆盖已有状态目录
600		if _, err := New(dir, Config{Seed: []byte("persist-seed"), Validators: vals, MaxTxsPerBlock: 5}); err == nil {
601			t.Fatal("New over existing state must fail")
602		}
603	}
604	
605	// 确定性：相同种子、初始配置与输入顺序，产生相同提议者、交易顺序、区块标识与确认历史。
606	func TestDeterminism(t *testing.T) {
607		keys := genKeys(t, 4)
608		build := func() ([]string, []Block, []byte, uint64) {
609			dir := t.TempDir()
610			vals := make([][]byte, len(keys))
611			for i, k := range keys {
612				vals[i] = append([]byte(nil), k.pub...)
613			}
614			n, err := New(dir, Config{Seed: []byte("determinism-seed"), Validators: vals, MaxTxsPerBlock: 3})
615			if err != nil {
616				t.Fatal(err)
617			}
618			var proposers []byte
619			for r := 1; r <= 3; r++ {
620				proposers = append(proposers, n.CurrentProposer()...)
621				// 固定的输入顺序
622				n.Submit(NewTransaction(keys[r%4].priv, uint64(r), []byte(fmt.Sprintf("c%d", r)), uint64((r*7)%13), 100))
623				n.Submit(NewTransaction(keys[(r+1)%4].priv, 1, []byte(fmt.Sprintf("d%d", r)), uint64(r), 100))
624				p, _ := n.Propose()
625				confirmByVotes(t, n, keys, p.BlockID)
626			}
627			var ids []string
628			for _, b := range n.st2Blocks() {
629				ids = append(ids, b.ID)
630			}
631			return ids, n.st2Blocks(), proposers, n.CurrentRound()
632		}
633		ids1, blocks1, prop1, round1 := build()
634		ids2, blocks2, prop2, round2 := build()
635		if fmt.Sprint(ids1) != fmt.Sprint(ids2) {
636			t.Fatalf("block ids differ:\n%v\n%v", ids1, ids2)
637		}
638		if string(prop1) != string(prop2) {
639			t.Fatal("proposers differ")
640		}
641		if round1 != round2 {
642			t.Fatal("rounds differ")
643		}
644		for i := range blocks1 {
645			if fmt.Sprint(blocks1[i].TxIDs) != fmt.Sprint(blocks2[i].TxIDs) {
646				t.Fatalf("tx order differs in block %d", i+1)
647			}
648		}
649	}
650	
651	// st2Blocks 是测试辅助：导出全部确认块。
652	func (n *Node) st2Blocks() []Block {
653		out := make([]Block, len(n.st.Blocks))
654		copy(out, n.st.Blocks)
655		return out
656	}
657	
658	// 提议者可查询且在名单内；同轮可复算。
659	func TestProposerQuery(t *testing.T) {
660		keys := genKeys(t, 4)
661		n, _ := newTestNode(t, keys, 10)
662		p := n.CurrentProposer()
663		found := false
664		for _, k := range keys {
665			if string(k.pub) == string(p) {
666				found = true
667			}
668		}
669		if !found {
670			t.Fatal("proposer not in validator set")
671		}
672		if string(n.ProposerFor(1)) != string(p) {
673			t.Fatal("ProposerFor(1) must equal current proposer")
674		}
675	}
676	
677	// 写入失败时一次确认不生效：内存保持确认前状态，磁盘也仍是确认前文件，
678	// 恢复后只能看到确认前的完整状态。
679	func TestConfirmAtomicityOnWriteFailure(t *testing.T) {
680		keys := genKeys(t, 4)
681		n, dir := newTestNode(t, keys, 10)
682		tx1 := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100)
683		n.Submit(tx1)
684		p, _ := n.Propose()
685		// 已有 1 票的状态先落盘
686		if _, err := n.Vote(keys[0].pub, 1, p.BlockID); err != nil {
687			t.Fatal(err)
688		}
689		before, err := os.ReadFile(filepath.Join(dir, stateFileName))
690		if err != nil {
691			t.Fatal(err)
692		}
693	
694		// 注入写入失败：决定性的第三票必须报错，且状态保持确认前。
695		n.injectSaveErr = errors.New("disk full (simulated)")
696		res, err := n.Vote(keys[1].pub, 1, p.BlockID)
697		if err == nil {
698			t.Fatal("expected save error")
699		}
700		if res != nil {
701			t.Fatalf("result should be nil on error, got %+v", res)
702		}
703		n.injectSaveErr = nil
704	
705		if n.Height() != 0 || n.CurrentRound() != 1 {
706			t.Fatalf("in-memory state changed despite failed write: height=%d round=%d", n.Height(), n.CurrentRound())
707		}
708		pp, ok := n.Proposal()
709		if !ok || pp.BlockID != p.BlockID {
710			t.Fatal("proposal must survive the failed confirmation")
711		}
712		info, _ := n.Tx(tx1.ID())
713		if info.Status != StatusProposed {
714			t.Fatalf("tx status = %s, want proposed (pre-confirmation state)", info.Status)
715		}
716		// 磁盘文件仍是确认前内容
717		after, err := os.ReadFile(filepath.Join(dir, stateFileName))
718		if err != nil {
719			t.Fatal(err)
720		}
721		if string(before) != string(after) {
722			t.Fatal("state file changed despite failed write")
723		}
724		// 模拟“中途停止后恢复”：Open 出来的也只能是确认前状态
725		reopened, err := Open(dir)
726		if err != nil {
727			t.Fatal(err)
728		}
729		if reopened.Height() != 0 || reopened.CurrentRound() != 1 {
730			t.Fatal("reopened node should show pre-confirmation state")
731		}
732		// keys[1] 那次投票没有计入，仍需两票才能确认
733		r2, err := reopened.Vote(keys[1].pub, 1, p.BlockID)
734		if err != nil || r2.Confirmed {
735			t.Fatalf("first post-reopen vote: %+v %v", r2, err)
736		}
737		r3, err := reopened.Vote(keys[2].pub, 1, p.BlockID)
738		if err != nil || !r3.Confirmed {
739			t.Fatalf("second post-reopen vote should confirm: %+v %v", r3, err)
740		}
741		if reopened.Height() != 1 {
742			t.Fatal("confirmation should now be durable")
743		}
744	}
745	
746	// 保存文件形态检查：状态目录下只有 state.json（临时文件已收尾）。
747	func TestStateFileLayout(t *testing.T) {
748		keys := genKeys(t, 4)
749		dir := t.TempDir()
750		vals := [][]byte{keys[0].pub, keys[1].pub, keys[2].pub}
751		n, err := New(filepath.Join(dir, "node"), Config{Seed: []byte("x"), Validators: vals, MaxTxsPerBlock: 2})
752		if err != nil {
753			t.Fatal(err)
754		}
755		n.Submit(NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100))
756		p, _ := n.Propose()
757		n.Vote(keys[0].pub, 1, p.BlockID)
758		entries, err := os.ReadDir(filepath.Join(dir, "node"))
759		if err != nil {
760			t.Fatal(err)
761		}
762		var names []string
763		for _, e := range entries {
764			names = append(names, e.Name())
765		}
766		if fmt.Sprint(names) != "[state.json]" {
767			t.Fatalf("unexpected files: %v", names)
768		}
769	}
