// 落选候选独有的交易回到排队；共享交易确认一次、落选候选不能改其状态；
// 进入新轮次时已到期的交易显示过期。
func TestLoserTransactionsReturnAndExpire(t *testing.T) {
	keys := genKeys(t, 4)
	n, _ := newTestNode(t, keys, 10)

	shared := NewTransaction(keys[0].priv, 1, []byte("shared"), 1, 3) // 进入轮次 3 时到期
	localOnly := NewTransaction(keys[1].priv, 1, []byte("local-only"), 1, 100)
	altOnly := NewTransaction(keys[2].priv, 1, []byte("alt-only"), 1, 100)
	for _, tx := range []*Transaction{shared, localOnly, altOnly} {
		n.Submit(tx)
	}
	// 构造一个只含 shared、localOnly 的本地提议：费用相同，标识顺序不可控，
	// 因此用单交易上限逐轮控制不方便；改为直接登记竞争候选并让其胜出，
	// 本地提议内容以实际返回为准。
	local, _ := n.Propose()
	// 竞争候选只含 shared 与 altOnly（两者都必须在池中排队或已提议）。
	alt, err := n.RegisterCandidate(1, []string{shared.ID(), altOnly.ID()})
	if err != nil {
		t.Fatal(err)
	}
	confirmCandidate(t, n, keys, alt.BlockID)

	// 若 shared 恰好在本地提议中，它仍是胜出交易；无论如何必须为 confirmed。
	info, _ := n.Tx(shared.ID())
	if info.Status != StatusConfirmed {
		t.Fatalf("shared tx status = %s, want confirmed", info.Status)
	}
	// altOnly 同样胜出确认。
	if info, _ := n.Tx(altOnly.ID()); info.Status != StatusConfirmed {
		t.Fatalf("altOnly status = %s, want confirmed", info.Status)
	}
	// 仅出现在落选本地提议中的交易回到排队。
	losers := []string{}
	for _, id := range local.TxIDs {
		if id == shared.ID() || id == altOnly.ID() {
			continue
		}
		losers = append(losers, id)
	}
	for _, id := range losers {
		info, _ := n.Tx(id)
		if info.Status != StatusQueued {
			t.Fatalf("loser-only tx %s status = %s, want queued", id, info.Status)
		}
	}
	if localOnly.ID() != shared.ID() {
		// localOnly 若在本地提议中则已回到排队，否则仍在池中排队；两种情况都必须是 queued。
		if info, _ := n.Tx(localOnly.ID()); info.Status != StatusQueued {
			t.Fatalf("localOnly status = %s, want queued", info.Status)
		}
	}

	// 第 2 轮不确认直接结束，进入第 3 轮，shared 等已确认不受影响；
	// 排队交易若到期（expiry=3 的未确认交易）显示过期。
	expiring := NewTransaction(keys[3].priv, 1, []byte("expiring"), 1, 3)
	n.Submit(expiring)
	p2, _ := n.Propose()
	if _, err := n.RegisterCandidate(2, p2.TxIDs); err != nil {
		t.Fatal(err)
	}
	if r, err := n.EndRound(); err != nil || r != 3 {
		t.Fatalf("end round = %d, %v", r, err)
	}
	if info, _ := n.Tx(expiring.ID()); info.Status != StatusExpired {
		t.Fatalf("expiring tx status = %s, want expired", info.Status)
	}
	// 已确认历史不变。
	if info, _ := n.Tx(shared.ID()); info.Status != StatusConfirmed {
		t.Fatalf("confirmed tx changed after round end: %s", info.Status)
	}
	if n.Height() != 1 {
		t.Fatal("EndRound must not create a block")
	}
}

